window.MOTIF_CATALOG_CHUNKS[24]={"cards":[{"id":"MEJE-KW-002497","row_version":1,"title":"평온한 이야기의 과거에 숨은 참사","original":"Backstory Horror","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"겉으로 가볍게 보이는 작품의 옛 사건에 잔혹한 결과가 숨어 있다. 현재의 밝은 분위기와 과거의 무게가 충돌한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002497/index.html"},{"id":"MEJE-KW-002498","row_version":2,"title":"새 인물이 오래전부터 있었던 사람으로 받아들여지기","original":"Backstory Invader","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"갑자기 나타난 인물을 주변 모두가 과거부터 함께 지낸 동료로 기억한다. 실제 역사와 바뀐 기억 사이의 차이가 세계의 이상을 알려 준다. 과거가 바뀐 듯한 인상은 시간 여행으로 초반 사건에 되돌아가기에서도 만들 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002498/index.html"},{"id":"MEJE-KW-002499","row_version":1,"title":"그날 이야기와 맞춰 새 과거사가 드러나기","original":"Backstory of the Day","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"기존 인물에게 앞서 언급되지 않은 경험이 갑자기 생겨 이번 회차의 사건을 설명한다. 새 정보가 풍성함을 주는지 편의적인 설정인지 살필 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002499/index.html"},{"id":"MEJE-KW-002500","row_version":1,"title":"표시 장치에 맞춰 화면 밝기를 바꾸기","original":"Back That Light Up","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"작품을 볼 화면의 밝기와 조명 조건에 맞춰 색과 명암을 조정한다. 같은 이미지라도 보는 기기에서 달라지는 인상을 제작 단계에서 고려한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002500/index.html"},{"id":"MEJE-KW-002501","row_version":2,"title":"등을 맞대고 포위망에 맞서기","original":"Back-to-Back Badasses","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"둘 이상의 인물이 서로 등을 지켜 주며 여러 방향의 적을 상대한다. 동작의 대칭이 실력뿐 아니라 신뢰를 보여 준다. 싸움의 동작을 정지된 이미지로 옮기면 등을 맞댄 두 인물의 포스터가 된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002501/index.html"},{"id":"MEJE-KW-002502","row_version":2,"title":"등을 맞댄 두 인물의 포스터","original":"Back-to-Back Poster","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"주요 인물 둘을 서로 반대쪽을 보며 나란히 세워 한 화면에 담는다. 협력하는 관계인지 충돌하는 관계인지 몸의 방향과 표정으로 암시한다. 두 인물이 등을 보이는 구도는 뒷모습으로 풍경을 바라보게 하기와 시선 배치가 다르다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002502/index.html"},{"id":"MEJE-KW-002503","row_version":2,"title":"강화 형태 대신 기본 모습으로 이기기","original":"Back to Base Form","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"여러 단계의 힘을 얻은 인물이 마지막 승부에서 평소 모습으로 싸워 이긴다. 강한 장비보다 처음부터 가진 판단과 의지를 결말의 중심에 놓는다. 마지막 승리는 강화 장비보다 전투 능력과 담력이 두드러진 인물의 선택을 드러낼 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002503/index.html"},{"id":"MEJE-KW-002504","row_version":1,"title":"뒷모습으로 풍경을 바라보게 하기","original":"\"Back to Camera\" Pose","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 관객에게 등을 보이고 화면 속 먼 곳을 바라본다. 표정보다 그가 보는 공간에 시선을 모아 관객이 같은 자리에 선 듯 느끼게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002504/index.html"},{"id":"MEJE-KW-002505","row_version":2,"title":"끝에서 시작으로 거꾸로 펼치는 이야기","original":"Back to Front","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"결과를 먼저 보여 주고 장면을 거슬러 올라가 원인에 도달한다. 관객은 무엇이 일어났는지보다 왜 그 결과가 생겼는지를 따라간다. 과거로 돌아가는 시간 여행으로 초반 사건에 되돌아가기와 달리 사건의 제시 순서만 바꾼다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002505/index.html"},{"id":"MEJE-KW-002506","row_version":1,"title":"어른이 다시 학교에 다니기","original":"Back to School","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"한때 학교를 떠났던 성인이 새 목적을 위해 학생으로 돌아간다. 이전의 경험과 현재의 교실 규칙이 어긋나며 배움과 관계가 달라진다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002506/index.html"},{"id":"MEJE-KW-002507","row_version":1,"title":"시간 여행으로 초반 사건에 되돌아가기","original":"Back to the Early Installment","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물들이 이미 관객이 본 작품 초반의 시점으로 이동한다. 과거 장면을 다시 보되 이후에 알게 된 사실이 같은 순간의 의미를 바꾼다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002507/index.html"},{"id":"MEJE-KW-002508","row_version":1,"title":"태어나기 이전 단계로 되돌아가기","original":"Back to the Womb","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법이나 초현실적 변화가 인물을 아기보다 앞선 상태까지 돌려보낸다. 나이를 되감는 규칙이 몸과 정체성의 경계를 건드리는 설정이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002508/index.html"},{"id":"MEJE-KW-002509","row_version":2,"title":"이미 지나간 게임 구간을 다시 탐색하기","original":"Backtracking","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"앞서 다녔던 장소로 돌아가 새 길이나 놓친 정보를 찾는다. 같은 지형이라도 얻은 능력과 달라진 목표 때문에 다른 길로 보인다. 이전 지역으로 돌아가지만 탈출했지만 출발한 곳으로 돌아오기처럼 실패한 탈출은 아니다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002509/index.html"},{"id":"MEJE-KW-002510","row_version":2,"title":"도움을 청했지만 동료가 개입하지 않기","original":"Backup Abstention","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"위기에 빠진 인물이 동료의 지원을 기대하지만 동료는 지켜보거나 떠난다. 두려움인지 책임을 묻는 선택인지에 따라 관계의 균열이 달라진다. 실제로 오지 않는 동료 대신 없는 지원군을 있는 듯 속이기로 시간을 벌 수도 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002510/index.html"},{"id":"MEJE-KW-002511","row_version":1,"title":"없는 지원군을 있는 듯 속이기","original":"Backup Bluff","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"수적으로 불리한 인물이 멀리서 지원군이 온다고 거짓말해 상대의 결정을 늦춘다. 실제 전력보다 상대가 믿는 정보가 잠시 우위를 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002511/index.html"},{"id":"MEJE-KW-002512","row_version":2,"title":"죽은 동료가 살아 있는 이들을 돕기","original":"Backup from Otherworld","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"세상을 떠난 인물이 영혼이나 초자연적 힘으로 현장에 개입한다. 기억 속 조언을 넘어 실제 사건을 바꾸는 도움이다. 죽은 이의 도움과 죽었다가 돌아오는 인물는 세계관의 죽음 규칙을 다르게 쓴다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002512/index.html"},{"id":"MEJE-KW-002513","row_version":2,"title":"죽은 인물과 똑같이 생긴 쌍둥이가 나타나기","original":"Backup Twin","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"상실한 인물의 자리에 처음 알려지는 쌍둥이가 들어온다. 외모가 같은 사람을 같은 인물처럼 대할지 별개의 삶으로 볼지가 관계의 쟁점이다. 죽음으로 돌아온 인물과 오랜만에 돌아온 인물이 곧 죽기는 외형이 같아도 다른 사건이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002513/index.html"},{"id":"MEJE-KW-002514","row_version":1,"title":"쏜 사람 쪽으로 공격이 돌아오는 장난 무기","original":"Backwards-Firing Gun","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"사용자가 예상한 방향과 반대로 공격이 향하도록 만든 허구의 무기. 함정이 드러나는 순간 사용자의 자신감이 실수로 뒤집힌다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002514/index.html"},{"id":"MEJE-KW-002515","row_version":1,"title":"밴조 소리로 외진 마을을 알리기","original":"Backwater Banjo","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"밴조의 음색을 시골이나 외딴 지역의 배경 신호로 사용한다. 소리만으로 장소를 짐작하게 하지만 지역 문화를 단순한 기호로 줄일 위험도 있다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002515/index.html"},{"id":"MEJE-KW-002516","row_version":1,"title":"전문 훈련 없이 열리는 뒷마당 레슬링","original":"Backyard Wrestling","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작은 공간에서 팬들이 직접 경기를 꾸미는 아마추어 레슬링 활동. 작품에서는 열정과 공연 욕구를 보여 주는 배경으로 쓰되 위험한 동작을 가볍게 다루지 않는다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-002516/index.html"},{"id":"MEJE-KW-002517","row_version":2,"title":"병균을 악마 같은 인물로 그리기","original":"Bacteria Devil","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"눈에 보이지 않는 병균이나 부패의 원인을 악의적인 캐릭터로 의인화한다. 몸과 음식의 변화를 선악 대결처럼 이해시키는 이미지다. 몸 안의 위협을 보이기 위해 검은 액체를 토해 이상을 알리기 같은 신체 신호를 쓸 수 있다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002517/index.html"},{"id":"MEJE-KW-002518","row_version":2,"title":"연기는 서툴지만 거짓말은 잘하는 인물","original":"Bad Actor, Good Liar","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"무대에 서면 어색한 사람이 사적인 대화에서는 상대를 능숙하게 속인다. 계획된 공연과 실제 이해관계가 걸린 기만을 다르게 해내는 성격이다. 극중의 연기 능력과 서투른 연기를 과장해 보여 주기을 표현하는 배우의 연기는 구분해야 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002518/index.html"},{"id":"MEJE-KW-002519","row_version":2,"title":"전투 능력과 담력이 두드러진 인물","original":"Badass","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험 앞에서 남다른 실력과 결단을 보이는 인물 유형. 겉모습의 과장보다 실제 선택과 결과가 그 평가를 뒷받침하는지 살핀다. 귀여운 모습과 실력을 겹친 귀여운 외형과 강한 실력을 함께 가진 인물도 이 유형에 포함될 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002519/index.html"},{"id":"MEJE-KW-002520","row_version":1,"title":"귀여운 외형과 강한 실력을 함께 가진 인물","original":"Badass Adorable","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"보호받아야 할 듯한 인상이지만 위기에서는 뛰어난 능력을 보인다. 외형으로 짐작한 역할과 실제 행동의 차이가 인물의 매력이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002520/index.html"},{"id":"MEJE-KW-002521","row_version":2,"title":"아이를 안고도 전투를 이어 가기","original":"Badass and Baby","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"싸움 중에 어린아이를 보호해야 해 인물이 한 손과 이동 경로에 제약을 안고 맞선다. 전투의 멋보다 아이의 안전이 판단의 기준이 된다. 한 전투의 순간을 넘어 동행이 이어지면 전투에 능한 보호자와 아이의 동행가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002521/index.html"},{"id":"MEJE-KW-002522","row_version":1,"title":"전투에 능한 보호자와 아이의 동행","original":"Badass and Child Duo","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"위험한 길에서 실력 있는 어른이 아이와 오래 함께 이동한다. 보호의 책임이 거친 인물의 선택을 바꾸고 아이에게도 스스로 판단할 자리를 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002522/index.html"},{"id":"MEJE-KW-002523","row_version":1,"title":"팔짱을 낀 채 상대를 압도하기","original":"Badass Arm-Fold","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 맞서는 상대 앞에서 팔을 접은 채 움직이지 않는다. 서두르지 않는 자세가 자신감이나 도발로 읽힌다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002523/index.html"},{"id":"MEJE-KW-002524","row_version":2,"title":"구성원 모두가 강한 군대","original":"Badass Army","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"소수의 영웅만이 아니라 병사 다수가 높은 실력과 결속을 지닌 군대. 개별 전투보다 훈련과 조직 전체의 위상이 위협이 된다. 소규모 팀으로 범위를 좁히면 구성원 모두가 실력자인 팀와 맞닿는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002524/index.html"},{"id":"MEJE-KW-002525","row_version":2,"title":"상대를 보지 않고 싸우기","original":"Badass Back","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 등을 돌린 채로 다가오는 적의 움직임을 읽고 공격을 막는다. 시야를 주지 않아도 우세하다는 과시가 장면의 핵심이다. 적에게 등을 보이는 행동과 등을 맞대고 포위망에 맞서기는 방향은 비슷해도 관계가 다르다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002525/index.html"},{"id":"MEJE-KW-002526","row_version":1,"title":"탄띠로 전투 태세를 드러내기","original":"Badass Bandolier","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"어깨나 가슴을 가로지르는 탄띠를 인물의 복식에 뚜렷하게 배치한다. 장비가 손에 닿는 거리와 싸움을 예상하는 태도가 한눈에 보인다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002526/index.html"},{"id":"MEJE-KW-002527","row_version":1,"title":"거친 거리에서도 태연한 오토바이 운전자","original":"Badass Biker","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험한 구역을 오토바이로 통과하며 두려움보다 자기 통제력을 보이는 인물. 탈것과 복장이 도시의 위협에 맞서는 인상을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002527/index.html"},{"id":"MEJE-KW-002528","row_version":2,"title":"전적을 힘 있게 늘어놓는 자기소개","original":"Badass Boast","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 맞서기 전에 이룬 일과 지닌 칭호를 길게 말해 상대를 위축시킨다. 사실과 허세가 얼마나 섞였는지가 뒤따르는 행동에서 드러난다. 말의 내용이 지속적인 원칙이라면 강한 인물의 신조 선언으로 읽을 수 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002528/index.html"},{"id":"MEJE-KW-002529","row_version":2,"title":"공부와 싸움에 모두 능한 인물","original":"Badass Bookworm","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"책과 지식을 가까이하는 인물이 필요할 때 신체적 위기도 잘 헤쳐 나간다. 지적인 역할과 행동하는 역할을 한 사람에게 겹친다. 초인적 능력이 없는 경우 초능력 없이 초인과 나란히 싸우는 인물와 역할이 겹칠 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002529/index.html"},{"id":"MEJE-KW-002530","row_version":1,"title":"행정 절차를 무기로 쓰는 실력자","original":"Badass Bureaucrat","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"서류와 규칙을 꿰뚫어 복잡한 조직 안에서 일을 해결하는 인물. 눈에 띄는 전투 없이도 결정권자의 움직임을 바꾼다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002530/index.html"},{"id":"MEJE-KW-002531","row_version":2,"title":"우연히 현장에 있던 사람이 실력으로 구하기","original":"Badass Bystander","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"도움을 받아야 할 듯했던 구경꾼이 숨겨 둔 능력으로 위기 해결에 나선다. 영웅과 일반인의 역할 경계가 한순간에 바뀐다. 평범한 신체의 준비와 판단은 초능력 없이 초인과 나란히 싸우는 인물와 연결된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002531/index.html"},{"id":"MEJE-KW-002532","row_version":2,"title":"망토로 인물의 위엄을 키우기","original":"Badass Cape","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"넓게 펼쳐지는 망토를 이용해 인물의 몸집과 움직임을 크게 보이게 한다. 색과 흔들림이 힘이나 권위를 전달하는 복식 연출이다. 현대적 복식에서는 긴 외투로 행동가의 실루엣 만들기로 같은 실루엣을 만들 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002532/index.html"},{"id":"MEJE-KW-002533","row_version":1,"title":"강한 인물의 신조 선언","original":"Badass Creed","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 자신이나 소속 집단이 따르는 짧은 원칙을 분명히 말한다. 말의 위엄보다 위기에서도 그 원칙을 지키는지가 인물을 완성한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002533/index.html"},{"id":"MEJE-KW-002534","row_version":2,"title":"구성원 모두가 실력자인 팀","original":"Badass Crew","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"팀원 한 사람만 돋보이는 대신 각자가 어려운 상황을 감당할 능력을 지닌 집단. 역할이 달라도 서로를 믿고 일을 나눌 수 있다. 혈연으로 묶인 집단이라면 가족 모두가 위기 대처에 능하기가 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002534/index.html"},{"id":"MEJE-KW-002535","row_version":2,"title":"한때 강했던 인물의 위상이 약해지기","original":"Badass Decay","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"이전에는 위협적이던 인물이 새 상대나 전개 속에서 자주 패배하고 영향력을 잃는다. 실제 능력의 감소인지 이야기의 비교 기준이 달라진 것인지 구분한다. 위상이 약해진 인물도 강한 인물이 혼자 해결할 수 없는 위기에 빠지기를 겪을 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002535/index.html"},{"id":"MEJE-KW-002536","row_version":1,"title":"위기 속에서 솜씨를 보여 주는 운전자","original":"Badass Driver","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"어려운 길과 추격에서도 운전으로 일행을 안전하게 이끄는 인물. 차량의 성능보다 순간적인 판단과 경로 선택에 초점을 둔다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002536/index.html"},{"id":"MEJE-KW-002537","row_version":1,"title":"머리띠로 전투 인상을 만들기","original":"Badasses Wear Bandanas","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"머리띠나 두건을 인물의 대표 복식으로 삼아 활동성과 결의를 강조한다. 작은 천 조각이 실루엣과 역할을 즉시 알아보게 한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002537/index.html"},{"id":"MEJE-KW-002538","row_version":1,"title":"가족 모두가 위기 대처에 능하기","original":"Badass Family","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 집안의 여러 구성원이 각자의 능력으로 위험에 대응한다. 힘을 물려받았다는 설정보다 가족 사이의 협력 방식이 집단의 성격을 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002538/index.html"},{"id":"MEJE-KW-002539","row_version":1,"title":"손가락을 튕겨 힘을 발동하기","original":"Badass Fingersnap","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"짧은 손가락 소리나 동작 하나에 거대한 힘이 응답한다. 작은 몸짓과 큰 결과의 간격으로 인물의 자신감을 보여 준다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002539/index.html"},{"id":"MEJE-KW-002540","row_version":1,"title":"단정한 정장으로 위험한 실력자를 보이기","original":"Badass in a Nice Suit","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"싸움에 익숙한 인물이 흐트러짐 없는 정장을 입어 전문성과 침착함을 드러낸다. 격식 있는 옷과 거친 행동의 대비가 인상을 만든다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002540/index.html"},{"id":"MEJE-KW-002541","row_version":2,"title":"강한 인물이 혼자 해결할 수 없는 위기에 빠지기","original":"Badass in Distress","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"늘 다른 사람을 구하던 인물이 부상이나 억류 때문에 도움을 받아야 한다. 능력이 사라진 것이 아니라 상황이 협력의 필요를 드러낸다. 학생을 구하는 학생을 지키려는 강한 교사도 도움을 받아야 하는 상황에 놓일 수 있다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-002541/index.html"},{"id":"MEJE-KW-002542","row_version":1,"title":"이스라엘 출신을 전투 전문가로 단정하는 묘사","original":"Badass Israeli","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"국적만으로 인물의 무술이나 무기 실력을 설명하는 정형화된 재현. 한 사람의 능력과 다양한 배경을 국가 이미지 하나로 압축하지 않도록 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002542/index.html"},{"id":"MEJE-KW-002543","row_version":1,"title":"긴 외투로 행동가의 실루엣 만들기","original":"Badass Longcoat","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"무릎 아래로 내려오는 외투를 인물의 대표 외형으로 사용한다. 걸음과 회전에서 옷자락이 흔들리며 행동의 크기와 비밀스러운 분위기를 더한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002543/index.html"},{"id":"MEJE-KW-002544","row_version":1,"title":"긴 로브로 신비로운 힘을 보이기","original":"Badass Long Robe","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"몸을 넓게 감싸는 로브를 통해 마법사나 수행자의 위엄을 만든다. 얼굴과 동작을 가리는 정도에 따라 친숙함보다 거리감이 커진다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002544/index.html"},{"id":"MEJE-KW-002545","row_version":2,"title":"말하지 않아도 호흡이 맞는 실력자들","original":"Badass Minds Think Alike","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"미리 계획하지 않았는데도 두 인물이 싸움 속에서 서로의 다음 행동을 정확히 맞춘다. 공유한 경험이나 비슷한 판단 방식이 대화의 빈자리를 채운다. 말없이 협력하는 호흡은 구성원 모두가 실력자인 팀의 팀워크를 보여 주는 한 방식이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002545/index.html"},{"id":"MEJE-KW-002546","row_version":1,"title":"원주민을 타고난 전사로 단순화하는 묘사","original":"Badass Native","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"토착 공동체 출신이라는 이유만으로 모두가 싸움에 능하다고 그리는 정형화. 문화와 개인의 차이를 전투 능력 하나로 줄이는 방식을 비판적으로 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002546/index.html"},{"id":"MEJE-KW-002547","row_version":1,"title":"초능력 없이 초인과 나란히 싸우는 인물","original":"Badass Normal","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"마법이나 초인적 신체가 없지만 준비와 훈련, 판단으로 강한 동료들과 함께 활약한다. 위험의 크기가 같아도 대처 수단은 다르다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002547/index.html"},{"id":"MEJE-KW-002548","row_version":1,"title":"전설 같은 업적에 비해 평범한 당사자","original":"Badass on Paper","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"이야기로 전해진 성취는 크지만 실제로 만난 인물은 어수룩하거나 수수하다. 업적의 사실과 인물의 일상적 태도가 동시에 참일 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002548/index.html"},{"id":"MEJE-KW-002549","row_version":2,"title":"폭력을 쓰지 않고도 단단한 인물","original":"Badass Pacifist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"싸울 능력의 과시 없이도 위험 앞에서 원칙을 지키며 다른 사람을 움직이는 인물. 비폭력의 선택을 무력함과 같게 보지 않는다. 초능력이 없는 인물도 초능력 없이 초인과 나란히 싸우는 인물처럼 폭력을 거부할 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002549/index.html"},{"id":"MEJE-KW-002550","row_version":1,"title":"싸움에 능한 설교자","original":"Badass Preacher","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소에는 신앙을 전하는 인물이 위기에서 직접 사람을 지킬 능력을 보인다. 종교적 역할과 물리적 대응 사이의 긴장을 인물의 선택으로 다룬다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002550/index.html"},{"id":"MEJE-KW-002551","row_version":1,"title":"산타가 직접 싸움에 나서기","original":"Badass Santa","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"선물과 축제의 상징인 산타를 전투나 구출의 주역으로 바꾼다. 익숙한 온화함과 뜻밖의 행동력이 한 인물 안에서 만난다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002551/index.html"},{"id":"MEJE-KW-002552","row_version":1,"title":"학생을 지키려는 강한 교사","original":"Badass Teacher","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"수업하는 모습만 보이던 교사가 학생을 위협하는 상황에 적극적으로 맞선다. 힘의 과시보다 보호할 책임이 행동의 이유가 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002552/index.html"},{"id":"MEJE-KW-002553","row_version":2,"title":"이식한 신체 부위가 능력의 원천이 되기","original":"Badass Transplant","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"기계나 마법으로 얻은 새로운 팔·다리·기관이 이전 몸에 없던 힘을 준다. 몸에 더해진 부분의 능력과 사용자의 의지가 어디서 만나는지 살핀다. 신체 부위의 힘에 의존한다는 점에서 초능력 없이 초인과 나란히 싸우는 인물와 경계를 구분한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002553/index.html"},{"id":"MEJE-KW-002554","row_version":2,"title":"원치 않지만 위기마다 실력을 발휘하는 인물","original":"Badass Unintentional","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평온하게 살고 싶어 하지만 사건이 닥치면 필요한 능력을 발휘해 사람을 돕는다. 성취 뒤에도 영웅의 지위를 바라지 않는 태도가 특징이다. 성취와 일상의 태도가 다른 전설 같은 업적에 비해 평범한 당사자와 겹칠 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002554/index.html"},{"id":"MEJE-KW-002555","row_version":1,"title":"서투른 연기를 과장해 보여 주기","original":"Bad \"Bad Acting\"","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"극중 인물이 연기를 못한다는 설정을 큰 몸짓과 뻣뻣한 대사로 전달한다. 실제 배우가 의도적으로 만든 어색함과 극중 인물의 실력을 구분해야 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002555/index.html"},{"id":"MEJE-KW-002556","row_version":1,"title":"침실 상태로 인물의 생활을 암시하기","original":"Bad Bedroom, Bad Life","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"잠자거나 쉬는 공간이 정리되지 않거나 쓰기 어려운 모습으로 등장한다. 방의 상태를 인물의 처지와 연결하되 개인의 성격을 단정하는 증거로 삼지 않는다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002556/index.html"},{"id":"MEJE-KW-002557","row_version":2,"title":"검은 액체를 토해 이상을 알리기","original":"Bad Black Barf","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 검고 끈적한 물질을 토해 몸 안에서 벌어지는 변화를 시각적으로 드러낸다. 병이나 저주의 원인을 말하기 전에 관객에게 위험을 예고한다. 병원체를 인물화한 병균을 악마 같은 인물로 그리기와 신체 증상을 연결할 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002557/index.html"},{"id":"MEJE-KW-002558","row_version":2,"title":"부하에게 잔혹한 상사","original":"Bad Boss","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"지시를 따르는 사람에게도 모욕과 위협을 일삼는 권력자. 외부의 적보다 가까운 조직 안에서 생기는 공포가 통치 방식을 드러낸다. 조직을 다루는 방식은 행정 절차를 무기로 쓰는 실력자와 대조된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002558/index.html"},{"id":"MEJE-KW-002559","row_version":2,"title":"가족용 작품 속 순화된 거친 인물","original":"Badbutt","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험한 능력과 강한 태도를 지녔지만 어린 관객을 위한 표현 범위에 맞춰 말과 행동이 순화된 인물. 힘의 설정과 화면에서 허용되는 행동의 간격이 특징이다. 화면의 표현 범위와 무관하게 전투 능력과 담력이 두드러진 인물의 행동 근거를 확인한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002559/index.html"},{"id":"MEJE-KW-002560","row_version":1,"title":"기대와 달리 엉망이 된 데이트","original":"Bad Date","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 알아가려던 만남에서 실수와 뜻밖의 사건이 겹쳐 계획이 무너진다. 불편한 시간을 함께 견딘 뒤 관계가 이어질지 갈라질지가 장면의 결과다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002560/index.html"},{"id":"MEJE-KW-002561","row_version":1,"title":"악당이 상대를 진심으로 칭찬하기","original":"Baddie Flattery","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"적대하는 인물이 싸우는 상대의 옷차림이나 실력을 차분하게 칭찬한다. 칭찬의 진심과 위협의 맥락이 겹쳐 듣는 사람을 더 불안하게 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002561/index.html"},{"id":"MEJE-KW-002562","row_version":1,"title":"해외판의 품질이 낮아지기","original":"Bad Export for You","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 다른 지역에 나왔지만 내용이나 편의 기능이 빠지고 가격 조건도 달라진다. 이용자가 같은 작품을 같은 조건으로 만나지 못하는 유통의 차이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002562/index.html"},{"id":"MEJE-KW-002563","row_version":2,"title":"주인공이 맞닥뜨린 어두운 미래","original":"Bad Future","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"현재의 선택이 실패했을 때를 보여 주는 미래 세계. 인물이 이미 벌어진 피해를 목격하며 돌아가 바꿔야 할 이유를 얻는다. 과거에서 온 사람이 보는 과거에서 온 사람이 현재를 실망스럽게 보기와는 시간의 방향이 다르다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002563/index.html"},{"id":"MEJE-KW-002564","row_version":1,"title":"신분증 대신 엉뚱한 물건을 내밀기","original":"Badge Gag","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"권한을 증명하려던 인물이 지갑이나 주머니에서 다른 카드를 꺼내 보인다. 엄숙한 절차가 작은 착오로 무너지는 순간이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002564/index.html"},{"id":"MEJE-KW-002565","row_version":1,"title":"군 경력을 지닌 경찰 인물","original":"Badges and Dog Tags","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"군 조직을 떠난 뒤 경찰로 일하는 인물. 과거의 훈련과 현재의 공적 권한이 같지 않으므로 그 차이를 인물의 판단과 갈등에 반영할 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002565/index.html"},{"id":"MEJE-KW-002566","row_version":1,"title":"거칠고 관능적인 여성 주연 만화","original":"Bad Girl Comic","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"강한 여성 주인공에게 폭력적 행동과 과장된 성적 이미지를 함께 부여하는 만화의 한 제작 관습. 주인공의 선택권과 시선의 대상이 되는 방식을 따로 살핀다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002566/index.html"},{"id":"MEJE-KW-002567","row_version":1,"title":"자유분방함을 선언하는 인물 소개 노래","original":"Bad Girl Song","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"여성 인물이 노래로 자신의 욕망과 생활 방식을 적극적으로 알린다. 다른 인물의 평가보다 스스로 고른 말과 리듬이 성격을 소개한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002567/index.html"},{"id":"MEJE-KW-002568","row_version":2,"title":"악당들이 모이는 술집","original":"Bad Guy Bar","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"서로 다른 범죄자와 반사회적 인물이 비밀스럽게 만나는 술집. 거래와 소문, 잠입의 경로가 한 장소에 모인다. 손님들의 관계를 보여 주는 일상 장면으로 당구장에 모인 악당들을 둘 수 있다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002568/index.html"},{"id":"MEJE-KW-002569","row_version":2,"title":"주인공 대신 악당이 꺼리는 일을 해치우기","original":"Bad Guys Do the Dirty Work","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"주인공은 선택하지 못한 거친 행동을 다른 적대자가 실행해 당장의 문제를 해결한다. 해결의 이익과 행동의 책임이 서로 다른 사람에게 남는다. 주인공이 감당하지 못한 일을 악당 조직이 더 많은 자원을 쥐기의 세력이 해치울 수도 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-002569/index.html"},{"id":"MEJE-KW-002570","row_version":1,"title":"악당 조직이 더 많은 자원을 쥐기","original":"Bad Guys Have Better Budgets","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"적대 세력의 장비와 자금이 주인공 편을 압도한다. 선악의 차이가 아니라 정보와 물자의 불균형이 승부의 조건이 된다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-002570/index.html"},{"id":"MEJE-KW-002571","row_version":1,"title":"당구장에 모인 악당들","original":"Bad Guys Play Pool","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"당구를 치는 장소를 악당의 친목과 정보 교환의 무대로 쓴다. 평범한 놀이가 인물의 위협적 이미지와 함께 배치되는 관습이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002571/index.html"},{"id":"MEJE-KW-002572","row_version":1,"title":"성직자 복장으로 신분을 속이기","original":"Bad Habits","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 종교인의 옷을 입고 다른 사람의 신뢰나 접근 권한을 얻는다. 옷이 지닌 사회적 권위를 위장의 도구로 바꾼다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002572/index.html"},{"id":"MEJE-KW-002573","row_version":1,"title":"중요한 날에 머리가 마음대로 되지 않기","original":"Bad Hair Day","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"외모를 정돈해야 할 시간에 머리 모양이 계획과 다르게 흐트러진다. 사소한 불편이 인물의 긴장과 자기 의식을 키운다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002573/index.html"},{"id":"MEJE-KW-002574","row_version":1,"title":"친숙한 이동 판매차가 위협을 숨기기","original":"Bad Humor Truck","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"아이들에게 익숙한 간식차나 이동 판매차를 범죄와 공포의 무대로 뒤집는다. 안전해 보이는 외형 때문에 경계가 늦어지는 상황을 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002574/index.html"},{"id":"MEJE-KW-002575","row_version":1,"title":"유명인 흉내를 어설프게 내기","original":"Bad Impressionists","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"인물이 알려진 사람의 목소리와 몸짓을 따라 하지만 특징을 제대로 잡지 못한다. 흉내 낸 사람보다 흉내 내는 사람의 자신감이 웃음의 원인이 된다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-002575/index.html"},{"id":"MEJE-KW-002576","row_version":1,"title":"팔로어를 속이는 온라인 인물","original":"Bad Influencer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"온라인에서 쌓은 신뢰를 이용해 왜곡된 정보나 무책임한 상품을 퍼뜨리는 인물. 영향력의 크기와 그 영향에 대한 책임이 충돌한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002576/index.html"},{"id":"MEJE-KW-002577","row_version":1,"title":"나쁜 것을 좋은 것으로 부르는 악당","original":"Bad Is Good and Good Is Bad","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"악당이 해로운 행동을 칭찬하고 선한 일을 혐오한다고 말한다. 가치의 언어를 뒤집어 자신이 속한 세계의 기준을 과장해 보여 준다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002577/index.html"},{"id":"MEJE-KW-002578","row_version":1,"title":"불편한 일에 더 민망한 유니폼을 입기","original":"Bad Job, Worse Uniform","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물이 달가워하지 않는 일을 하면서 우스꽝스럽거나 낙인처럼 보이는 복장까지 강요받는다. 일의 조건과 남의 시선이 겹쳐 굴욕감이 커진다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002578/index.html"},{"id":"MEJE-KW-002579","row_version":1,"title":"거짓말을 전혀 그럴듯하게 하지 못하기","original":"Bad Liar","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 사실을 감추려 하지만 말이 꼬이거나 꾸며 낸 내용이 금세 들통난다. 거짓말의 성공보다 숨기고 싶은 마음이 선명해지는 인물 유형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002579/index.html"},{"id":"MEJE-KW-002580","row_version":2,"title":"불운을 불러온다고 여겨지는 물건","original":"Bad Luck Charm","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"누군가 갖고 있으면 나쁜 일이 이어진다고 믿는 물건. 실제 저주인지 우연을 묶어 해석한 결과인지는 작품의 규칙에 따라 달라진다. 게임에서는 불운의 반복을 연속 실패를 완화하는 게임 규칙으로 조절할 수 있다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002580/index.html"},{"id":"MEJE-KW-002581","row_version":1,"title":"연속 실패를 완화하는 게임 규칙","original":"Bad Luck Mitigation Mechanic","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"확률에 좌우되는 보상을 계속 놓치면 다음 기회가 조금씩 좋아지거나 일정 횟수 뒤 결과를 보장한다. 우연의 재미와 반복 실패의 피로를 조정한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002581/index.html"},{"id":"MEJE-KW-002582","row_version":1,"title":"돌보던 아이에게 끊임없이 시달리는 보호자","original":"Badly Battered Babysitter","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"아이를 맡은 사람이 예상 밖의 이동과 소동을 계속 수습한다. 아이의 안전을 지키는 책임과 돌봄 제공자의 지침이 함께 보인다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002582/index.html"},{"id":"MEJE-KW-002583","row_version":2,"title":"기분이 나쁘다는 이유로 행동을 변명하기","original":"Bad Mood as an Excuse","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 화가 났거나 지쳤다는 사실을 남에게 한 행동의 면책처럼 내세운다. 감정의 이유와 행동의 책임을 따로 묻게 되는 장면이다. 타인에게 상처를 준 뒤 기분이 상하면 찾아가는 혼자만의 장소에 숨는다고 책임이 사라지지는 않는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002583/index.html"},{"id":"MEJE-KW-002584","row_version":1,"title":"기분이 상하면 찾아가는 혼자만의 장소","original":"Bad Mood Retreat","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"인물이 슬픔이나 분노가 커질 때 늘 찾는 조용한 공간. 그곳을 아는 사람이 있는지에 따라 고립 또는 위로의 장소가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002584/index.html"},{"id":"MEJE-KW-002585","row_version":2,"title":"붉거나 이상한 달로 재앙을 예고하기","original":"Bad Moon Rising","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"평소와 다른 색과 크기의 달이 떠오르며 큰 사건이 다가옴을 알린다. 하늘의 변화를 세계의 불길한 신호로 읽는 상징이다. 하늘의 징후와 함께 작은 떨림으로 거대한 위협을 알리기을 배치하면 위협을 느끼게 할 수 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002585/index.html"},{"id":"MEJE-KW-002586","row_version":2,"title":"나쁜 소식을 좋게 포장해서 말하기","original":"Bad News in a Good Way","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"전해야 할 손해와 실패를 밝히면서도 표현과 순서를 바꿔 덜 심각하게 보이게 한다. 듣는 사람이 사실을 알게 되는 순간 포장의 의도도 드러난다. 사소한 이득을 내세우는 큰 불행에 사소한 좋은 소식을 덧붙이기와 말의 방향이 가깝다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002586/index.html"},{"id":"MEJE-KW-002587","row_version":1,"title":"큰 불행에 사소한 좋은 소식을 덧붙이기","original":"Bad News, Irrelevant News","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"심각한 피해를 알린 뒤 거의 관계없는 작은 이득을 좋은 소식이라고 전한다. 두 정보의 크기 차이가 상황의 절망과 화자의 감각을 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002587/index.html"},{"id":"MEJE-KW-002588","row_version":1,"title":"오소리를 거칠게 그리는 동물 이미지","original":"Bad Ol' Badger","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"작품 속 오소리가 공격적이고 고집 센 동물로 반복해서 묘사된다. 실제 동물의 성질을 단정하기보다 이야기에서 맡은 역할과 이미지를 다룬다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002588/index.html"},{"id":"MEJE-KW-002589","row_version":1,"title":"위로하려고 꺼낸 이야기가 더 불길하기","original":"Bad Omen Anecdote","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"긴장한 사람을 달래려던 인물이 비슷한 사건의 나쁜 결말을 들려준다. 위로의 의도와 내용의 방향이 어긋나 불안이나 웃음이 생긴다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002589/index.html"},{"id":"MEJE-KW-002590","row_version":1,"title":"동물에게 잔혹한 행동으로 악역을 알리기","original":"Bad People Abuse Animals","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 방어하기 어려운 동물을 함부로 대하는 장면으로 위험한 성향을 보여 준다. 폭력을 장식으로 쓰지 않고 그 행동이 주변에 남기는 의미를 살핀다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-002590/index.html"},{"id":"MEJE-KW-002591","row_version":2,"title":"불길한 힘을 받아 악행에 쓰는 인물","original":"Bad Powers, Bad People","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"손에 넣은 능력이 남을 해치기 쉬운 성질을 지녔고 사용자가 그 방향을 선택한다. 능력의 외형만이 아니라 쓰기로 한 사람의 판단이 중요하다. 같은 힘을 가진 이가 불길한 힘을 선한 목적에 쓰려는 인물을 선택할 수도 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002591/index.html"},{"id":"MEJE-KW-002592","row_version":2,"title":"불길한 힘을 선한 목적에 쓰려는 인물","original":"Bad Powers, Good People","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위협적으로 보이는 능력을 가진 인물이 사람을 돕는 방법을 찾는다. 힘의 성질과 사용자의 의도를 분리해 보여 준다. 힘의 외형만으로 불길한 힘을 받아 악행에 쓰는 인물라고 단정하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002592/index.html"},{"id":"MEJE-KW-002593","row_version":1,"title":"과거에서 온 사람이 현재를 실망스럽게 보기","original":"Bad Present","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"먼 과거의 인물이 현재에 와서 자신이 바라던 발전과 다른 현실을 본다. 익숙한 일상을 낯선 가치 기준으로 다시 바라보게 한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002593/index.html"},{"id":"MEJE-KW-002594","row_version":2,"title":"이기적인 동기로 좋은 일을 하기","original":"Bad Reason to Do Good","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"남을 돕는 행동을 하면서도 칭찬과 인정 같은 자기 이익을 주된 이유로 삼는다. 행동의 결과와 동기에 대한 평가는 같은 방향일 필요가 없다. 동기가 다른 이에게 당장의 해결을 맡기는 주인공 대신 악당이 꺼리는 일을 해치우기와 구분한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002594/index.html"},{"id":"MEJE-KW-002595","row_version":1,"title":"혹평을 빌미로 특혜를 요구하기","original":"Bad Review Threat","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"인물이 나쁜 평가를 남기겠다고 위협해 가게나 창작자에게 원하는 대우를 얻으려 한다. 의견을 말할 권한이 협상의 압박으로 바뀌는 상황이다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-002595/index.html"},{"id":"MEJE-KW-002596","row_version":2,"title":"도움을 주는 척 접근하는 위험한 사람","original":"Bad Samaritan","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"길을 잃거나 다친 인물에게 친절을 베푸는 사람이 다른 의도를 숨긴다. 도움을 거절하기 어려운 상황을 악용해 신뢰를 위협으로 바꾼다. 친숙한 외형이 위협으로 바뀌는 축제의 산타가 위협적인 존재로 바뀌기와 위험의 출발점이 닮았다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002596/index.html"}]}.cards;